import itertools
def R(cells):
    S=set(cells)
    while True:
        new={tuple(map(max,zip(x,y))) for x in S for y in S}|{tuple(map(min,zip(x,y))) for x in S for y in S}
        if new<=S: return S
        S|=new
def E(c): return len(R(c))-len(set(c))
def four_gamete_fails(hs,m):
    """classical test: some pair of sites lacks one of its 4 combinations"""
    for i,j in itertools.combinations(range(m),2):
        seen={(h[i],h[j]) for h in hs}
        if len(seen)<4: return True
    return False

print("SENSITIVITY OF E AGAINST THE CLASSICAL FOUR-GAMETE TEST")
print(f"{'m':>2} {'subsets':>9} {'4G fails':>9} {'E>0':>7} {'E>0 & 4G':>9} {'sensitivity':>12}")
for m in (2,3,4):
    full=list(itertools.product([0,1],repeat=m)); tot=fg=eg=both=0
    for k in range(2,2**m+1):
        for s in itertools.combinations(full,k):
            tot+=1; f=four_gamete_fails(s,m); e=E(s)>0
            fg+=f; eg+=e; both+= (f and e)
    print(f"{m:>2} {tot:>9} {fg:>9} {eg:>7} {both:>9} {both/fg:>11.1%}")
print("\n  E>0 implies the four-gamete test fails (E is SOUND):",)
# check soundness
bad=0
for m in (2,3):
    full=list(itertools.product([0,1],repeat=m))
    for k in range(2,2**m+1):
        for s in itertools.combinations(full,k):
            if E(s)>0 and not four_gamete_fails(s,m): bad+=1
print(f"    counterexamples to soundness: {bad}")
print("\n  the two m=2 cases E misses are exactly the CHAINS:")
for s in [((0,0),(0,1),(1,1)),((0,0),(1,0),(1,1))]:
    print(f"    {list(s)}  E={E(s)}  chain under the product order, no incomparable pair")
